@-moz-document domain("messenger.com") {
:root {
    --dracula-background: #282A36;
    --dracula-current-line: #6272A4;
    --dracula-selection: #44475A;
    --dracula-foreground: #F8F8F2;
    --dracula-comment: #6272A4;
    --dracula-cyan: #8BE9FD;
    --dracula-green: #50FA7B;
    --dracula-orange: #FFB86C;
    --dracula-pink: #FF79C6;
    --dracula-purple: #BD93F9;
    --dracula-red: #FF5555;
    --dracula-yellow: #F1FA8C;
    --accent: var(--dracula-purple);
    --blue-link: var(--dracula-cyan);
    --primary-text: var(--dracula-foreground);
    --secondary-text: var(--dracula-comment);
    --primary-icon: var(--dracula-foreground);
    --secondary-icon: var(--dracula-comment);
    --disabled-text: var(--dracula-comment);
    --disabled-icon: var(--dracula-comment);
    --placeholder-text: var(--dracula-comment);
    --wash: var(--dracula-background);
    --web-wash: var(--dracula-background);
    --surface-background: var(--dracula-background);
    --card-background: var(--dracula-background);
    --card-background-flat: var(--dracula-background);
    --comment-background: var(--dracula-selection);
    --input-background: var(--dracula-selection);
    --popover-background: var(--dracula-selection);
    --divider: var(--dracula-selection);
    --hover-overlay: rgba(248, 248, 242, .1);
    --press-overlay: rgba(248, 248, 242, .2);
    --background-deemphasized: rgba(248, 248, 242, .1);
    --primary-button-background: var(--dracula-purple);
    --primary-button-text: var(--dracula-foreground);
    --secondary-button-background: var(--dracula-selection);
    --secondary-button-text: var(--dracula-foreground);
    --disabled-button-background: var(--dracula-selection);
    --disabled-button-text: var(--dracula-comment);
    --button-background-color-selected: var(--dracula-current-line);
    --chat-composer-background-color: var(--dracula-selection);
    --chat-composer-button-color: var(--dracula-purple);
    --chat-composer-caret-color: var(--dracula-purple);
    --chat-composer-input-text-placeholder-color: var(--dracula-comment);
    --chat-incoming-message-bubble-background-color: var(--dracula-selection);
    --chat-outgoing-message-bubble-background-color: var(--dracula-purple);
    --chat-incoming-message-text-color: var(--dracula-foreground);
    --chat-message-text-color: var(--dracula-foreground);
    --chat-replied-message-background-color: rgba(98, 114, 164, 0.2);
    --chat-delivery-receipt-color: var(--dracula-cyan);
    --chat-admin-text-color: var(--dracula-foreground);
    --chat-edit-message-overlay-color: var(--dracula-selection);
    --mwp-header-background-color: var(--dracula-background);
    --mwp-header-button-color: var(--dracula-purple);
    --mwp-header-text-color: var(--dracula-foreground);
    --nav-bar-background: var(--dracula-background);
    --nav-bar-background-gradient: linear-gradient(to top, var(--dracula-background), rgba(40, 42, 54, .9), rgba(40, 42, 54, .7), rgba(40, 42, 54, .4), rgba(40, 42, 54, 0));
    --nav-bar-background-gradient-wash: linear-gradient(to top, var(--dracula-background), rgba(40, 42, 54, .9), rgba(40, 42, 54, .7), rgba(40, 42, 54, .4), rgba(40, 42, 54, 0));
    --fb-wordmark: var(--dracula-foreground);
    --messenger-card-background: var(--dracula-background);
    --messenger-reply-background: var(--dracula-selection);
    --mwp-message-row-background: transparent;
    --mwp-primary-theme-color: var(--dracula-purple);
    --mwp-subheader-text-color: var(--dracula-purple);
    --reaction-pill-background-color: var(--dracula-selection);
    --reaction-pill-multireact-selected-color: var(--dracula-foreground);
    --text-highlight: rgba(189, 147, 249, 0.4);
    --positive: var(--dracula-green);
    --negative: var(--dracula-red);
    --warning: var(--dracula-yellow);
    --text-positive: var(--dracula-green);
    --text-negative: var(--dracula-red);
    --text-warning: var(--dracula-yellow);
    --positive-background: rgba(80, 250, 123, .2);
    --negative-background: rgba(255, 85, 85, .2);
    --base-blue: var(--dracula-cyan);
    --base-cherry: var(--dracula-pink);
    --base-grape: var(--dracula-purple);
    --base-lemon: var(--dracula-yellow);
    --base-lime: var(--dracula-green);
    --base-pink: var(--dracula-pink);
    --base-seafoam: var(--dracula-cyan);
    --base-teal: var(--dracula-cyan);
    --base-tomato: var(--dracula-orange);
    --chat-scrollbar-thumb-color: var(--dracula-current-line);
    --chat-scrollbar-track-color: transparent;
    --scrollbar-thumb-color: var(--dracula-current-line);
    --scrollbar-track-color: transparent;
    --fds-primary-icon: var(--dracula-foreground);
    --fds-primary-text: var(--dracula-foreground);
    --fds-comment-background: var(--dracula-selection);
    --fds-white: var(--dracula-background);
    --fds-black: var(--dracula-foreground);
    --always-white: var(--dracula-foreground);
    --always-black: var(--dracula-background);
    --buttonSendBackgroundColor: var(--dracula-purple);
}

* {
    color: #F8F8F2 !important;
}

span {
		color: #8BE9FD !important;
}

path {
    color: var(--dracula-cyan) !important;
}
body, button, input, label, select, td, textarea, html, :host {
    font-family: 'Inter', 'Roboto', Helvetica, Arial, sans-serif;
    color: var(--dracula-foreground) !important;
}

body {
    background-color: var(--dracula-background) !important;
    color: var(--dracula-foreground) !important;
    line-height:inherit;
    margin:0;
}

._6s5d {
    background-color: var(--web-wash);
}

._9dls ._6s5d {
    overflow-y: visible !important;
}

a, a:visited {
    color: var(--dracula-cyan) !important;
}

[role="heading"], [data-testid="thread-name"] {
    color: var(--dracula-pink) !important;
}

