[aria-label="Inbox switcher"] {
    border: 2px solid var(--dracula-selection); 
		border-radius: 20px 20px 20px 20px;
    background-color: rgba(0,0,0,0.1);
    padding-top: 8px; 
  	padding-bottom: 8px;
  	padding-left: 4px;
  	padding-right: 4px;
    transition: border-color 0.3s ease-in-out, box-shadow 0.3s ease-in-out;

}

